UPDATE organization_role_definitions SET capabilities_json=json_insert(capabilities_json,'$[#]','suppliers.write') WHERE role='accountant';
-- One capability source for API checks and atomic database guards.
UPDATE organization_role_definitions SET capabilities_json=json_insert(capabilities_json,'$[#]','bookings.all') WHERE role IN('dispatcher','operations_admin','sales_agent');
UPDATE organization_role_definitions SET capabilities_json=json_insert(capabilities_json,'$[#]','reports.read') WHERE role='dispatcher';
CREATE VIEW organization_vehicle_access AS SELECT DISTINCT m.user_id,v.operator_id,v.id AS vehicle_id FROM memberships m JOIN users u ON u.id=m.user_id AND u.status='active' JOIN vehicles v ON v.operator_id=m.operator_id WHERE EXISTS(SELECT 1 FROM organization_capabilities c WHERE c.user_id=m.user_id AND c.operator_id=m.operator_id AND c.capability IN('*','fleet.all','fleet.basic')) OR EXISTS(SELECT 1 FROM organization_effective_roles e WHERE e.user_id=m.user_id AND e.operator_id=m.operator_id AND e.role='driver') AND (EXISTS(SELECT 1 FROM premium_assignments a WHERE a.vehicle_id=v.id AND a.driver_user_id=m.user_id) OR EXISTS(SELECT 1 FROM standard_drivers dr WHERE dr.id=v.default_driver_id AND dr.user_id=m.user_id) OR EXISTS(SELECT 1 FROM standard_departure_drivers td JOIN standard_drivers dr ON dr.id=td.driver_id JOIN departures d ON d.id=td.departure_id WHERE d.vehicle_id=v.id AND dr.user_id=m.user_id)) OR EXISTS(SELECT 1 FROM organization_effective_roles e JOIN organization_vehicle_access_grants g ON g.user_id=e.user_id AND g.operator_id=e.operator_id WHERE e.user_id=m.user_id AND e.operator_id=m.operator_id AND e.role='vehicle_owner' AND g.vehicle_id=v.id);
CREATE VIEW organization_departure_access AS SELECT DISTINCT m.user_id,v.operator_id,d.id AS departure_id FROM memberships m JOIN users u ON u.id=m.user_id AND u.status='active' JOIN vehicles v ON v.operator_id=m.operator_id JOIN departures d ON d.vehicle_id=v.id WHERE EXISTS(SELECT 1 FROM organization_capabilities c WHERE c.user_id=m.user_id AND c.operator_id=m.operator_id AND c.capability IN('*','trips.read')) AND (EXISTS(SELECT 1 FROM organization_capabilities c WHERE c.user_id=m.user_id AND c.operator_id=m.operator_id AND c.capability IN('*','trips.all')) OR EXISTS(SELECT 1 FROM organization_effective_roles e WHERE e.user_id=m.user_id AND e.operator_id=m.operator_id AND e.role='driver') AND (EXISTS(SELECT 1 FROM standard_departure_drivers td JOIN standard_drivers dr ON dr.id=td.driver_id WHERE td.departure_id=d.id AND dr.user_id=m.user_id) OR NOT EXISTS(SELECT 1 FROM standard_departure_drivers td JOIN standard_drivers dr ON dr.id=td.driver_id WHERE td.departure_id=d.id AND dr.user_id IS NOT NULL) AND EXISTS(SELECT 1 FROM premium_assignments a WHERE a.vehicle_id=v.id AND a.driver_user_id=m.user_id)) OR EXISTS(SELECT 1 FROM organization_effective_roles e JOIN organization_vehicle_access_grants g ON g.user_id=e.user_id AND g.operator_id=e.operator_id WHERE e.user_id=m.user_id AND e.operator_id=m.operator_id AND e.role='vehicle_owner' AND g.vehicle_id=v.id));
CREATE VIEW organization_departure_operation AS SELECT a.* FROM organization_departure_access a JOIN departures d ON d.id=a.departure_id WHERE EXISTS(SELECT 1 FROM organization_capabilities c WHERE c.user_id=a.user_id AND c.operator_id=a.operator_id AND c.capability IN('*','trips.operate')) AND (EXISTS(SELECT 1 FROM organization_capabilities c WHERE c.user_id=a.user_id AND c.operator_id=a.operator_id AND c.capability IN('*','trips.operate_all')) OR EXISTS(SELECT 1 FROM organization_effective_roles e WHERE e.user_id=a.user_id AND e.operator_id=a.operator_id AND e.role='driver') AND (EXISTS(SELECT 1 FROM standard_departure_drivers td JOIN standard_drivers dr ON dr.id=td.driver_id WHERE td.departure_id=d.id AND dr.user_id=a.user_id) OR NOT EXISTS(SELECT 1 FROM standard_departure_drivers td JOIN standard_drivers dr ON dr.id=td.driver_id WHERE td.departure_id=d.id AND dr.user_id IS NOT NULL) AND EXISTS(SELECT 1 FROM premium_assignments p WHERE p.vehicle_id=d.vehicle_id AND p.driver_user_id=a.user_id)));
CREATE VIEW organization_vehicle_operation AS SELECT a.* FROM organization_vehicle_access a WHERE EXISTS(SELECT 1 FROM organization_capabilities c WHERE c.user_id=a.user_id AND c.operator_id=a.operator_id AND c.capability IN('*','trips.operate')) AND (EXISTS(SELECT 1 FROM organization_capabilities c WHERE c.user_id=a.user_id AND c.operator_id=a.operator_id AND c.capability IN('*','trips.operate_all')) OR EXISTS(SELECT 1 FROM organization_effective_roles e JOIN premium_assignments p ON p.operator_id=e.operator_id AND p.driver_user_id=e.user_id WHERE e.user_id=a.user_id AND e.operator_id=a.operator_id AND e.role='driver' AND p.vehicle_id=a.vehicle_id));
CREATE VIEW organization_service_access AS SELECT DISTINCT m.user_id,x.operator_id,b.id AS service_id,'booking' AS kind FROM bookings b JOIN standard_booking_details x ON x.booking_id=b.id JOIN memberships m ON m.operator_id=x.operator_id WHERE EXISTS(SELECT 1 FROM organization_capabilities c WHERE c.user_id=m.user_id AND c.operator_id=m.operator_id AND c.capability IN('*','bookings.read')) AND (EXISTS(SELECT 1 FROM organization_capabilities c WHERE c.user_id=m.user_id AND c.operator_id=m.operator_id AND c.capability IN('*','bookings.all')) OR b.departure_id IS NOT NULL AND EXISTS(SELECT 1 FROM organization_departure_operation a WHERE a.user_id=m.user_id AND a.departure_id=b.departure_id) OR b.departure_id IS NULL AND EXISTS(SELECT 1 FROM organization_vehicle_operation a WHERE a.user_id=m.user_id AND a.vehicle_id=x.vehicle_id)) UNION SELECT DISTINCT m.user_id,b.operator_id,b.id,'custom' FROM standard_custom_bookings b JOIN memberships m ON m.operator_id=b.operator_id WHERE EXISTS(SELECT 1 FROM organization_capabilities c WHERE c.user_id=m.user_id AND c.operator_id=m.operator_id AND c.capability IN('*','bookings.read')) AND (EXISTS(SELECT 1 FROM organization_capabilities c WHERE c.user_id=m.user_id AND c.operator_id=m.operator_id AND c.capability IN('*','bookings.all')) OR EXISTS(SELECT 1 FROM organization_vehicle_operation a WHERE a.user_id=m.user_id AND a.vehicle_id=b.vehicle_id));
DROP TRIGGER premium_assignment_insert_valid;
DROP TRIGGER premium_assignment_update_valid;
CREATE TRIGGER premium_assignment_insert_valid BEFORE INSERT ON premium_assignments WHEN NOT EXISTS(SELECT 1 FROM vehicles v JOIN premium_branches b ON b.operator_id=v.operator_id WHERE v.id=NEW.vehicle_id AND v.operator_id=NEW.operator_id AND b.id=NEW.branch_id) OR NEW.driver_user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM organization_effective_roles e WHERE e.user_id=NEW.driver_user_id AND e.operator_id=NEW.operator_id AND e.role='driver') BEGIN SELECT RAISE(ABORT,'assignment_conflict'); END;
CREATE TRIGGER premium_assignment_update_valid BEFORE UPDATE ON premium_assignments WHEN NOT EXISTS(SELECT 1 FROM vehicles v JOIN premium_branches b ON b.operator_id=v.operator_id WHERE v.id=NEW.vehicle_id AND v.operator_id=NEW.operator_id AND b.id=NEW.branch_id) OR NEW.driver_user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM organization_effective_roles e WHERE e.user_id=NEW.driver_user_id AND e.operator_id=NEW.operator_id AND e.role='driver') BEGIN SELECT RAISE(ABORT,'assignment_conflict'); END;
DROP TRIGGER standard_driver_account_valid;
DROP TRIGGER standard_driver_account_insert;
CREATE TRIGGER standard_driver_account_valid BEFORE UPDATE OF user_id ON standard_drivers WHEN NEW.user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM organization_effective_roles WHERE operator_id=NEW.operator_id AND user_id=NEW.user_id AND role='driver') BEGIN SELECT RAISE(ABORT,'assignment_conflict'); END;
CREATE TRIGGER standard_driver_account_insert BEFORE INSERT ON standard_drivers WHEN NEW.user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM organization_effective_roles WHERE operator_id=NEW.operator_id AND user_id=NEW.user_id AND role='driver') BEGIN SELECT RAISE(ABORT,'assignment_conflict'); END;
DROP TRIGGER standard_gps_active;
CREATE TRIGGER standard_gps_active BEFORE INSERT ON standard_gps_positions WHEN NOT EXISTS(SELECT 1 FROM standard_tracking t WHERE t.id=NEW.trip_id AND t.mode='operations' AND t.service_status='running' AND NEW.vehicle_id=COALESCE((SELECT vehicle_id FROM departures WHERE id=t.departure_id),(SELECT vehicle_id FROM standard_booking_details WHERE booking_id=t.booking_id),(SELECT vehicle_id FROM standard_custom_bookings WHERE id=t.custom_booking_id)) AND (t.departure_id IS NOT NULL AND EXISTS(SELECT 1 FROM organization_departure_operation a WHERE a.user_id=NEW.actor_id AND a.departure_id=t.departure_id) OR t.departure_id IS NULL AND EXISTS(SELECT 1 FROM organization_vehicle_operation a WHERE a.user_id=NEW.actor_id AND a.vehicle_id=NEW.vehicle_id))) BEGIN SELECT RAISE(ABORT,'gps_access_changed'); END;
INSERT OR IGNORE INTO schema_migrations(version) VALUES('0039_organization_scopes');
